/// Catalog of the host-card icons, keyed by lower-case id. [OsCatalog.get]
/// always returns a valid descriptor ('unknown' as fallback).
///
/// Every icon is a single-colour inline SVG from `host_icon_svgs.dart`
/// (generated by `tool/host_icons/gen_host_icons.py`): the OS / brand marks
/// are Simple Icons paths, the generic ones a matching family of 24px line
/// icons. They are tinted at render time, with the host's own colour label
/// when it has one, else [OsDescriptor.brandColor]; see `OsIcon`.
///
/// Ids are persisted (`connections.icon_id`, synced) and produced by OS
/// detection, so an id is never renamed: the ones that predate the line-icon
/// set (`shell`, `git`, `kubernetes`, `file_server`, ...) keep their id and
/// simply point at the matching new glyph.
class OsCatalog {
  OsCatalog._();

  static final Map<String, OsDescriptor> _map = {
    for (final d in _all) d.id: d,
  };

  /// Returns the descriptor for [osId], falling back to `unknown`.
  static OsDescriptor get(String? osId) =>
      _map[osId?.toLowerCase() ?? ''] ?? _map['unknown']!;

  /// Every icon the host-card icon picker offers, minus the internal
  /// 'unknown' fallback.
  static List<OsDescriptor> get pickable =>
      _all.where((d) => d.id != 'unknown').toList(growable: false);

  /// The pickable icons of one category, in catalog order.
  static List<OsDescriptor> inCategory(HostIconCategory category) =>
      pickable.where((d) => d.category == category).toList(growable: false);

  /// Case-insensitive match on id, name and keywords, and the name [nameOf]
  /// gives (the icon's name in the person's language), every word of the
  /// query having to hit. An empty query returns everything.
  static List<OsDescriptor> search(String query, {String Function(OsDescriptor icon)? nameOf}) {
    final words = query
        .toLowerCase()
        .split(RegExp(r'\s+'))
        .where((w) => w.isNotEmpty)
        .toList();
    if (words.isEmpty) return pickable;
    return pickable.where((d) {
      final hay = [
        d.id.replaceAll('_', ' '),
        d.displayName.toLowerCase(),
        if (nameOf != null) nameOf(d).toLowerCase(),
        ...d.keywords,
        d.category.name,
      ].join(' ');
      return words.every(hay.contains);
    }).toList(growable: false);
  }

  // ---------------------------------------------------------------------------
  // Builders
  // ---------------------------------------------------------------------------

  /// Render an inline single-colour SVG in [color]: the colour filter paints
  /// strokes and fills alike, so line icons and filled marks tint the same.
  static Widget _svg(String svg, double size, Color color) {
    return SvgPicture.string(
      svg,
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(color, BlendMode.srcIn),
    );
  }

  static OsDescriptor _brand(
    String id,
    String name,
    int hex, {
    List<String> keywords = const [],
  }) {
    final svg = kHostBrandIconSvgs[id]!;
    return OsDescriptor(
      id: id,
      displayName: name,
      brandColor: Color(hex),
      category: HostIconCategory.os,
      keywords: keywords,
      iconBuilder: (size, color) => _svg(svg, size, color),
    );
  }

  /// A generic line icon. [svgKey] names the glyph when the id predates the
  /// set; [color] overrides the category colour for the ids that always had
  /// a colour of their own.
  static OsDescriptor _line(
    String id,
    String name,
    HostIconCategory category, {
    String? svgKey,
    int? color,
    List<String> keywords = const [],
  }) {
    final svg = kHostLineIconSvgs[svgKey ?? id]!;
    return OsDescriptor(
      id: id,
      displayName: name,
      brandColor: Color(color ?? _categoryColor(category)),
      category: category,
      keywords: keywords,
      iconBuilder: (size, color) => _svg(svg, size, color),
    );
  }

  static int _categoryColor(HostIconCategory c) => switch (c) {
        HostIconCategory.os => 0xFF71717A,
        HostIconCategory.hardware => 0xFF64748B,
        HostIconCategory.network => 0xFF3B82F6,
        HostIconCategory.cloud => 0xFF38BDF8,
        HostIconCategory.services => 0xFF8B5CF6,
        HostIconCategory.security => 0xFFEF4444,
        HostIconCategory.places => 0xFF14B8A6,
        HostIconCategory.tags => 0xFFF97316,
      };

